<?php require 'config.php';require 'auth.php';requireLogin();$pageTitle='Tambah Kategori';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name==='')$errors[]='Nama kategori wajib diisi.';else{$c=read_data('categories');$c[]=['id'=>next_id($c),'name'=>$name,'description'=>$desc];write_data('categories',$c);$_SESSION['flash']=['type'=>'success','message'=>'Kategori berhasil ditambahkan.'];redirect('categories.php');}}include 'header.php';?><section class="page-heading"><div><h1>Tambah Kategori</h1></div></section><div class="form-card"><?php foreach($errors as $x):?><div class="alert alert-error"><?=e($x)?></div><?php endforeach;?><form method="post"><div class="form-group"><label>Nama Kategori</label><input name="name" required></div><div class="form-group"><label>Deskripsi</label><textarea name="description"></textarea></div><div class="form-actions"><button class="btn btn-primary">Simpan</button><a class="btn btn-secondary" href="categories.php">Batal</a></div></form></div><?php include 'footer.php';?>